<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {request} from './workbench-api';
const props=defineProps({bases:{type:Array,default:()=>[]},initialTaskId:{type:String,default:''}});
const scope=ref(''),mode=ref('configured'),tasks=ref([]),total=ref(0),page=ref(1),selected=ref(null),items=ref([]),itemTotal=ref(0),itemPage=ref(1),itemStatus=ref(''),worker=ref(null),busy=ref(false),error=ref('');
let timer,sequence=0;const selectedId=ref(props.initialTaskId);
const names={queued:'等待执行',running:'执行中',pause_requested:'正在暂停',paused:'已暂停',cancel_requested:'正在取消',cancelled:'已取消',completed:'已完成',partial:'部分完成',failed:'失败',pending:'待处理',stale:'资料已变更'};
const label=s=>names[s]||s;
const progress=computed(()=>selected.value?.total?Math.round(100*selected.value.processed/selected.value.total):0);
async function load(){const seq=++sequence;try{const result=await request(`/tasks?page=${page.value}&page_size=20`);if(seq!==sequence)return;tasks.value=result.items;total.value=result.total;worker.value=result.worker;
 const id=selectedId.value||result.items[0]?.task_id;if(!id){selected.value=null;items.value=[];return;}
 selectedId.value=id;const [task,detail]=await Promise.all([request('/tasks/'+id),request(`/tasks/${id}/items?page=${itemPage.value}&page_size=50${itemStatus.value?'&status='+itemStatus.value:''}`)]);
 if(seq!==sequence)return;selected.value=task;items.value=detail.items;itemTotal.value=detail.total;
}catch(e){if(seq===sequence)error.value=e.message;}}
async function action(run){if(busy.value)return;busy.value=true;error.value='';try{await run();await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function create(kind){await action(async()=>{const result=await request('/tasks',{method:'POST',body:{kind,knowledge_base_id:scope.value||null,runtime_mode:mode.value}});selectedId.value=result.task_id;itemPage.value=1;page.value=1;});}
async function control(task,command){if(command==='cancel'&&!confirm('取消剩余任务？当前小批完成后停止，原件及已完成结果保留。'))return;await action(()=>request(`/tasks/${task.task_id}/${command}`,{method:'POST'}));}
function choose(task){selectedId.value=task.task_id;itemPage.value=1;itemStatus.value='';load();}
watch(()=>props.initialTaskId,id=>{selectedId.value=id;itemPage.value=1;load();});
watch([page,itemPage],load);watch(itemStatus,()=>{itemPage.value=1;load();});
onMounted(()=>{load();timer=setInterval(load,2000);});onBeforeUnmount(()=>{clearInterval(timer);sequence++;});
</script>
<template><div class="wb-task-center"><section class="wb-card"><small>BACKGROUND TASKS</small><h2>批量处理与图文索引</h2><p class="wb-muted">任务逐批保存进度。暂停和取消在当前小批结束后生效，重启后继续未完成的本地任务。</p><div class="wb-task-create"><label class="wb-field">处理范围<select v-model="scope" aria-label="任务知识库"><option value="">全部知识库（含专属资料）</option><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label class="wb-field">索引模型<select v-model="mode" aria-label="任务索引模式"><option value="configured">真实模型 · 本地配置</option><option value="offline">离线 Hash 验证</option></select></label><button class="wb-button primary" :disabled="busy||!worker?.running" @click="create('index')">预建文本向量</button><button class="wb-button" :disabled="busy||!worker?.running" @click="create('image')">图片 OCR 与视觉索引</button><button class="wb-button" :disabled="busy||!worker?.running" @click="create('multimodal_index')">预建图文语义向量</button><button class="wb-button" :disabled="busy||!worker?.running" @click="create('vision_describe')">生成图片可见内容描述</button><button class="wb-button" :disabled="busy||!worker?.running" @click="create('image_frames')">补齐动图 OCR / 特征帧</button><button class="wb-button" :disabled="busy||!worker?.running" @click="create('process')">处理待解析文档</button></div><p class="wb-footnote">已入库文档保留当前编辑内容；索引复用相同内容的向量。图片描述使用本地预训练模型并自动检查来源与描述边界，画面事实审核另行记录。资料变更项标记为过期，需对当前版本新建任务。</p><div v-if="worker&&!worker.running" class="wb-alert error">后台执行器未运行，请检查后端启动状态。</div><div v-if="error" role="alert" class="wb-alert error">{{error}}</div></section>
<div class="wb-task-grid"><section class="wb-card"><div class="wb-between"><div><small>TASKS</small><h3>任务列表</h3></div><span class="wb-badge">{{total}}</span></div><div class="wb-task-list"><button v-for="task in tasks" :key="task.task_id" :class="{active:selectedId===task.task_id}" @click="choose(task)"><strong>{{task.kind==='multimodal_index'?'图文语义索引':task.kind==='vision_describe'?'图片可见内容描述':task.kind==='index'?'文本索引':task.kind==='image'?'图片 OCR / 视觉索引':task.kind==='image_frames'?'动图逐帧处理':'文档解析'}} · {{label(task.status)}}</strong><p>{{task.processed}} / {{task.total}} 项 · {{task.config.multimodal_fingerprint?.split(':')[0]||task.config.model?.model||(['image','image_frames'].includes(task.kind)?'Apple Vision · 本地图片处理':'本地解析')}}</p><small>{{task.task_id}}</small></button><div v-if="!tasks.length" class="wb-empty">尚无后台任务。</div></div><div class="wb-between wb-pagination"><button class="wb-button tiny" :disabled="page===1" @click="page--">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button class="wb-button tiny" :disabled="page*20>=total" @click="page++">下一页</button></div></section>
<section class="wb-card"><div class="wb-between"><div><small>PROGRESS</small><h3>任务进度与结果</h3></div><span v-if="selected" class="wb-badge">{{label(selected.status)}}</span></div><template v-if="selected"><p class="wb-muted wb-task-id">{{selected.task_id}}</p><progress :value="selected.processed" :max="selected.total" :aria-label="'任务进度 '+progress+'%'"/><p>{{selected.processed}} / {{selected.total}} · {{progress}}%</p><div class="wb-task-counts"><span>完成 {{selected.counts.completed||0}}</span><span>失败 {{selected.counts.failed||0}}</span><span>过期 {{selected.counts.stale||0}}</span><span>缓存复用 {{selected.cache_hits}}</span></div><div class="wb-actions"><button v-if="['queued','running'].includes(selected.status)" class="wb-button" :disabled="busy" @click="control(selected,'pause')">暂停任务</button><button v-if="selected.status==='paused'" class="wb-button primary" :disabled="busy" @click="control(selected,'resume')">继续任务</button><button v-if="['failed','partial'].includes(selected.status)&&(selected.counts.failed||selected.counts.pending)" class="wb-button primary" :disabled="busy" @click="control(selected,'retry')">重试未完成项</button><button v-if="['queued','running','paused','pause_requested','failed','partial'].includes(selected.status)" class="wb-button danger" :disabled="busy" @click="control(selected,'cancel')">取消任务</button></div><p v-if="selected.error" role="alert" class="wb-error-text">{{selected.error}}</p><label class="wb-field">明细状态<select v-model="itemStatus" aria-label="任务明细状态"><option value="">全部</option><option v-for="s in ['pending','running','completed','failed','stale']" :value="s" :key="s">{{label(s)}}</option></select></label><div class="wb-task-items"><article v-for="item in items" :key="item.ordinal"><strong>{{label(item.status)}} · {{item.source_name}}</strong><p>{{item.key}}</p><p v-if="item.error" class="wb-error-text">{{item.error}}</p><p v-if="item.output?.ocr_status">OCR：{{item.output.ocr_status==='completed'?'已识别文字':'未检测到文字'}} · {{item.output.visual_dimension}}d 视觉特征</p><small>执行 {{item.attempts}} 次<span v-if="item.output?.cache_hit"> · 已复用缓存</span></small></article><div v-if="!items.length" class="wb-empty">没有符合条件的明细。</div></div><div class="wb-between wb-pagination"><button class="wb-button tiny" :disabled="itemPage===1" @click="itemPage--">明细上一页</button><span>{{itemPage}} / {{Math.max(1,Math.ceil(itemTotal/50))}}</span><button class="wb-button tiny" :disabled="itemPage*50>=itemTotal" @click="itemPage++">明细下一页</button></div></template><div v-else class="wb-empty">选择任务查看进度。</div></section></div></div></template>
